public class ConsumersTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.List<String> log = new java.util.ArrayList<>();
            java.util.function.Consumer<String> c =
                    Consumers.both(x -> log.add("first:" + x), x -> log.add("second:" + x));
            c.accept("go");
            check("both runs a then b", "[first:go, second:go]", log.toString());
            c.accept("again");
            check("the combined consumer is reusable",
                    "[first:go, second:go, first:again, second:again]", log.toString());
        } catch (RuntimeException e) {
            System.out.println("FAIL  both usage -- threw " + e.getClass().getSimpleName());
            failures += 2;
        }

        try {
            java.util.List<String> trace = new java.util.ArrayList<>();
            java.util.function.Consumer<Integer> combo =
                    Consumers.both(n -> trace.add("double:" + (n * 2)), n -> trace.add("plain:" + n));
            combo.accept(5);
            check("both works for Integer", "[double:10, plain:5]", trace.toString());
        } catch (RuntimeException e) {
            System.out.println("FAIL  both with Integer -- threw " + e.getClass().getSimpleName());
            failures += 1;
        }

        try {
            java.util.List<String> sink = new java.util.ArrayList<>();
            java.util.function.Consumer<String> app = Consumers.appendTo(sink);
            app.accept("x");
            app.accept("y");
            check("appendTo collects values in order", "[x, y]", sink.toString());
            check("sink holds exactly the accepted values", 2, sink.size());

            Consumers.both(Consumers.appendTo(sink), Consumers.appendTo(sink)).accept("z");
            check("both of two appendTo consumers adds twice", "[x, y, z, z]", sink.toString());
        } catch (RuntimeException e) {
            System.out.println("FAIL  appendTo usage -- threw " + e.getClass().getSimpleName());
            failures += 3;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

