public class Consumers {

    public static <T> java.util.function.Consumer<T> both(
            java.util.function.Consumer<T> a, java.util.function.Consumer<T> b) {
        return value -> {
            a.accept(value);
            b.accept(value);
        };
    }

    public static java.util.function.Consumer<String> appendTo(java.util.List<String> sink) {
        return sink::add;
    }
}
